"The prayer St. Ignatius never wanted his companions to skip: five short steps to look back on the day with God.": "A oração que santo Inácio nunca quis que seus companheiros deixassem: cinco passos curtos para rever o dia com Deus.",
"Gregorian chant and beloved Catholic hymns, with recordings and the words in Latin and English: the Salve Regina, Pange Lingua, Veni Creator, Adeste Fideles, and more.": "Canto gregoriano e hinos católicos queridos, com gravações e a letra em latim e em inglês: a Salve Regina, o Pange Lingua, o Veni Creator, o Adeste Fideles e outros.",
"The Hours of Our Lady, from Matins to Compline, following the seasons of the year. A beloved prayer of religious, tertiaries, and those who wear the Brown Scapular.": "As Horas de Nossa Senhora, das Matinas às Completas, seguindo os tempos do ano. Uma oração querida dos religiosos, dos terciários e de quem usa o escapulário do Carmo.",
"The Brown and Green Scapulars, the Miraculous and St. Benedict Medals, First Fridays and First Saturdays, and holy water: what each one is, how to keep it, and its prayers.": "Os escapulários do Carmo e verde, a Medalha Milagrosa e a de São Bento, as primeiras sextas-feiras e os primeiros sábados, e a água benta: o que é cada um, como vivê-lo e suas orações.",
"The ancient prayer of the Incarnation, prayed at morning, noon, and evening. During the Easter season, the Regina Caeli.": "A antiga oração da Encarnação, rezada de manhã, ao meio-dia e à tarde. No tempo pascal, o Regina Caeli.",
"Pray with a passage of Scripture the way the monks did: read, reflect, respond, and rest in God.": "Reze com uma passagem da Escritura como faziam os monges: ler, meditar, responder e descansar em Deus.",
"Keep a private record of your daily prayer, build a steady habit, and see your faithfulness over the weeks.": "Mantenha um registro privado da sua oração diária, crie um hábito constante e veja a sua fidelidade ao longo das semanas.",
"Every part of the Mass in order, with when to stand, sit, and kneel, and what each moment means. Follow along on your phone at Mass.": "Cada parte da Missa em ordem, com quando ficar de pé, sentar e ajoelhar, e o significado de cada momento. Acompanhe no celular durante a Missa.",
"Every pope from St. Peter to Leo XIV, century by century.": "Todos os papas, de São Pedro a Leão XIV, século a século.",
"The great religious orders of the Church: monks, canons, friars, clerks regular, sisters, and the military orders of the crusades.": "As grandes ordens religiosas da Igreja: monges, cônegos, frades, clérigos regulares, irmãs e as ordens militares das cruzadas.",
"The most famous icons of East and West, what they show, and the stories behind them.": "Os ícones mais famosos do Oriente e do Ocidente, o que mostram e as histórias por trás deles.",
"The twenty-three Eastern Catholic Churches, in full communion with Rome: their traditions, leaders, and lands.": "As vinte e três Igrejas católicas orientais, em plena comunhão com Roma: suas tradições, seus pastores e suas terras.",
"How to become Catholic or come home, the basics of everyday Catholic life, and guides to discerning and living each vocation: marriage, priesthood, religious life, and more.": "Como se tornar católico ou voltar para casa, o básico da vida católica de cada dia e guias para discernir e viver cada vocação: matrimônio, sacerdócio, vida religiosa e outras.",
"The lists every Catholic learns, explained: the Ten Commandments, the Beatitudes, the precepts, the sacraments, the virtues, the works of mercy, the capital sins, and more.": "As listas que todo católico aprende, explicadas: os Dez Mandamentos, as Bem-aventuranças, os mandamentos da Igreja, os sacramentos, as virtudes, as obras de misericórdia, os pecados capitais e outras.",
"A walk through a Catholic church: what each part is for, the sacred vessels, the vestments, the colors of the seasons, and how to take part in the Mass.": "Um passeio por uma igreja católica: para que serve cada parte, os vasos sagrados, as vestes, as cores dos tempos e como participar da Missa.",
"All twenty-one ecumenical councils, from Nicaea to Vatican II: when and where they met, and what each one taught.": "Os vinte e um concílios ecumênicos, de Niceia ao Vaticano II: quando e onde se reuniram e o que cada um ensinou.",
"Clear, short definitions of the words of the Catholic faith, from Absolution to the Vulgate.": "Definições curtas e claras das palavras da fé católica, de “absolvição” a “Vulgata”.",
"The words of the saints, from the Church Fathers to our own day, each with its source. Search them, browse by theme, and share your favorites.": "As palavras dos santos, dos Padres da Igreja aos nossos dias, cada uma com a sua fonte. Pesquise, explore por tema e compartilhe as suas favoritas.",
