"The Chaplet of Divine Mercy": "O Terço da Misericórdia",
"Jesus, I trust in You": "Jesus, eu confio em vós",
"Jesus, I trust in You.": "Jesus, eu confio em vós.",
"Eternal Father": "Eterno Pai",
"For the Sake of His Sorrowful Passion": "Pela sua dolorosa Paixão",
"Holy God": "Deus Santo",
"Eternal Father, I offer You the Body and Blood, Soul and Divinity of Your dearly beloved Son, Our Lord Jesus Christ, in atonement for our sins and those of the whole world.": "Eterno Pai, eu vos ofereço o Corpo e Sangue, Alma e Divindade de vosso diletíssimo Filho, Nosso Senhor Jesus Cristo, em expiação dos nossos pecados e dos do mundo inteiro.",
"For the sake of His sorrowful Passion, have mercy on us and on the whole world.": "Pela sua dolorosa Paixão, tende misericórdia de nós e do mundo inteiro.",
"Holy God, Holy Mighty One, Holy Immortal One, have mercy on us and on the whole world.": "Deus Santo, Deus Forte, Deus Imortal, tende piedade de nós e do mundo inteiro.",
"You expired, Jesus, but the source of life gushed forth for souls, and an ocean of mercy opened up for the whole world. O Fount of Life, unfathomable Divine Mercy, envelop the whole world and empty Yourself out upon us.": "Expirastes, Jesus, mas a fonte de vida jorrou para as almas e abriu-se o oceano de misericórdia para o mundo inteiro. Ó fonte de vida, insondável Misericórdia Divina, envolvei o mundo inteiro e derramai-vos sobre nós.",
"Eternal God, in whom mercy is endless and the treasury of compassion inexhaustible, look kindly upon us and increase Your mercy in us, that in difficult moments we might not despair nor become despondent, but with great confidence submit ourselves to Your holy will, which is Love and Mercy itself.": "Deus eterno, em quem a misericórdia é infinita e o tesouro da compaixão inesgotável, olhai-nos com bondade e multiplicai em nós a vossa misericórdia, para que nos momentos difíceis não desesperemos nem desanimemos, mas com grande confiança nos submetamos à vossa santa vontade, que é o próprio Amor e a própria Misericórdia.",
"How to pray the Chaplet": "Como rezar o Terço",
"Begin with the Sign of the Cross and the opening prayer.": "Comece com o sinal da cruz e a oração inicial.",
"Pray one Our Father, one Hail Mary, and the Apostles’ Creed.": "Reze um Pai-Nosso, uma Ave-Maria e o Credo dos Apóstolos.",
"On each large bead, pray “Eternal Father, I offer You…”": "Em cada conta grande, reze “Eterno Pai, eu vos ofereço…”",
"On each of the ten small beads, pray “For the sake of His sorrowful Passion…”": "Em cada uma das dez contas pequenas, reze “Pela sua dolorosa Paixão…”",
"It is the Hour of Mercy now.": "Agora é a Hora da Misericórdia.",
"You have prayed the Chaplet of Divine Mercy": "Você rezou o Terço da Misericórdia",
"Pray the Chaplet again": "Rezar o Terço de novo",
"The Chaplet of the Sacred Heart": "O Terço do Sagrado Coração",
"Chaplet of the Sacred Heart": "Terço do Sagrado Coração",
"Sweet Heart of Jesus, be my love": "Doce Coração de Jesus, sede o meu amor",
"Sweet Heart of Jesus, be my love.": "Doce Coração de Jesus, sede o meu amor.",
"Sweet Heart of Mary": "Doce Coração de Maria",
"Sweet Heart of Mary, be my salvation.": "Doce Coração de Maria, sede a minha salvação.",
"O Sweetest Heart of Jesus": "Ó dulcíssimo Coração de Jesus",
"O Sweetest Heart of Jesus, I implore that I may ever love Thee more and more.": "Ó dulcíssimo Coração de Jesus, fazei que eu vos ame cada vez mais.",
"May the Heart of Jesus in the Most Blessed Sacrament be praised, adored, and loved with grateful affection, at every moment, in all the tabernacles of the world, even to the end of time. Amen.": "Seja louvado, adorado e amado com grato afeto, em todo momento, o Coração de Jesus no Santíssimo Sacramento, em todos os sacrários do mundo, até o fim dos tempos. Amém.",
"Soul of Christ": "Alma de Cristo",
"Soul of Christ, sanctify me.": "Alma de Cristo, santificai-me.",
"Body of Christ, save me.": "Corpo de Cristo, salvai-me.",
"Blood of Christ, inebriate me.": "Sangue de Cristo, inebriai-me.",
"Water from the side of Christ, wash me.": "Água do lado de Cristo, lavai-me.",
"Passion of Christ, strengthen me.": "Paixão de Cristo, confortai-me.",
"O good Jesus, hear me.": "Ó bom Jesus, ouvi-me.",
"Within thy wounds hide me.": "Dentro de vossas chagas, escondei-me.",
"Suffer me not to be separated from thee.": "Não permitais que me separe de vós.",
"From the malicious enemy defend me.": "Do espírito maligno, defendei-me.",
"In the hour of my death call me": "Na hora da minha morte, chamai-me",
"and bid me come unto thee,": "e mandai-me ir para vós,",
"that with thy saints I may praise thee": "para que com os vossos santos vos louve",
"forever and ever. Amen.": "por todos os séculos dos séculos. Amém.",
"The pendant": "A medalha",
"Thirty-three beads · about {n} minutes": "Trinta e três contas · cerca de {n} minutos",
"On the crucifix, make the Sign of the Cross and pray the Soul of Christ (Anima Christi).": "No crucifixo, faça o sinal da cruz e reze a Alma de Cristo (Anima Christi).",
"On each small bead, pray “Sweet Heart of Jesus, be my love.”": "Em cada conta pequena, reze “Doce Coração de Jesus, sede o meu amor.”",
"After each group of small beads, pray “Sweet Heart of Mary, be my salvation.”": "Depois de cada grupo de contas pequenas, reze “Doce Coração de Maria, sede a minha salvação.”",
"You have prayed the Chaplet of the Sacred Heart": "Você rezou o Terço do Sagrado Coração",
