"Apologetics: the reasons behind the faith, and charitable answers to the questions and objections Catholics most often hear.": "Apologética: as razões da fé e respostas caridosas às perguntas e objeções que os católicos mais ouvem.",
"Simple Words": "Em palavras simples",
"Ten questions drawn at random from the saints, books, Church history, the Bible, and theology on Sanctify. Every quiz is different.": "Dez perguntas sorteadas sobre os santos, os livros, a história da Igreja, a Bíblia e a teologia do Sanctify. Cada quiz é diferente.",
"Start the quiz": "Começar o quiz",
"Lives, feast days, patronages, and prayers of intercession, from the apostles to saints of our own time. Browse by era and walk of life, or search by what they are patrons of.": "Vidas, festas, padroados e orações de intercessão, dos apóstolos aos santos do nosso tempo. Explore por época e estado de vida, ou procure pelo que são padroeiros.",
