"Pray the Rosary bead by bead with the fifteen traditional mysteries, Joyful, Sorrowful, and Glorious, and a meditation for each.": "Reze o Rosário conta a conta com os quinze mistérios tradicionais, gozosos, dolorosos e gloriosos, e uma meditação para cada um.",
