"The twenty-sixth Sunday after Pentecost. The Mass of a Sunday after Epiphany that was left over earlier in the year is said.": "XXVI domingo depois de Pentecostes. Diz-se a missa de um domingo depois da Epifania que ficou por celebrar no início do ano.",
"The twenty-seventh Sunday after Pentecost. The Mass of a Sunday after Epiphany that was left over earlier in the year is said.": "XXVII domingo depois de Pentecostes. Diz-se a missa de um domingo depois da Epifania que ficou por celebrar no início do ano.",
"The twenty-eighth Sunday after Pentecost. The Mass of a Sunday after Epiphany that was left over earlier in the year is said.": "XXVIII domingo depois de Pentecostes. Diz-se a missa de um domingo depois da Epifania que ficou por celebrar no início do ano.",
