"The Most Holy Trinity": "Santíssima Trindade",
"The Most Sacred Heart of Jesus": "Sacratíssimo Coração de Jesus",
"Our Lord Jesus Christ the King": "Nosso Senhor Jesus Cristo Rei",
"The Commemoration of All the Faithful Departed (All Souls)": "Comemoração de todos os fiéis defuntos (Finados)",
"Twenty-Fourth and Last Sunday after Pentecost": "XXIV e último domingo depois de Pentecostes",
"The Sunday within the Octave of Christmas": "Domingo na oitava do Natal",
"Fridays are days of penance throughout the year.": "As sextas-feiras são dias de penitência durante todo o ano.",
"The Lord’s Day: Mass is an obligation for Catholics.": "Dia do Senhor: a missa é obrigatória para os católicos.",
"A day of fasting and abstinence.": "Dia de jejum e abstinência.",
"A Friday of Lent: a day of abstinence from meat.": "Sexta-feira da Quaresma: dia de abstinência de carne.",
"Kept on the Sunday between the Octave Day of Christmas and the Epiphany, or else on January 2.": "Celebrada no domingo entre a oitava do Natal e a Epifania, ou então a 2 de janeiro.",
"The First Sunday after the Epiphany.": "Primeiro domingo depois da Epifania.",
"The name means “seventieth,” counting toward Easter. The Gloria and Alleluia fall silent, and violet is worn until Easter.": "O nome significa «septuagésimo», contando até a Páscoa. Calam-se o Glória e o Aleluia, e usa-se o roxo até a Páscoa.",
"Lent begins. Ashes are blessed and imposed: “Memento, homo, quia pulvis es, et in pulverem reverteris.”": "Começa a Quaresma. As cinzas são bentas e impostas: «Memento, homo, quia pulvis es, et in pulverem reverteris.»",
"An Ember Day: by tradition a day of fasting and prayer for the season, and for those to be ordained.": "Dia de Têmporas: por tradição, dia de jejum e oração pela estação do ano e pelos que vão ser ordenados.",
"Named from the first word of its Introit, “Rejoice.” Rose vestments may be worn.": "O nome vem da primeira palavra do seu intróito, «Alegrai-vos». Podem usar-se paramentos cor-de-rosa.",
"Passiontide begins, and the crosses and images in the church are veiled.": "Começa o Tempo da Paixão, e as cruzes e imagens da igreja são cobertas.",
"Commemorated on the Friday after Passion Sunday.": "Comemoradas na sexta-feira depois do Domingo da Paixão.",
"The Second Sunday of the Passion. Palms are blessed and carried in procession.": "Segundo domingo da Paixão. Os ramos são bentos e levados em procissão.",
"The Mass of the Lord’s Supper, the washing of feet, and the stripping of the altars.": "A missa da Ceia do Senhor, o lava-pés e o desnudamento dos altares.",
"The solemn afternoon liturgy of the Passion, with the adoration of the Cross. No Mass is said.": "A solene liturgia vespertina da Paixão, com a adoração da Cruz. Não se diz missa.",
"The Easter Vigil is kept at night.": "A Vigília Pascal celebra-se à noite.",
"The feast of feasts.": "A festa das festas.",
"Within the octave of Easter.": "Na oitava da Páscoa.",
"The Octave Day of Easter (Dominica in Albis).": "Oitava da Páscoa (Dominica in Albis).",
"The Lesser Litanies: the Litany of the Saints is chanted, traditionally in procession, to ask God’s blessing on the fields.": "Ladainhas Menores: canta-se a Ladainha de Todos os Santos, tradicionalmente em procissão, para pedir a bênção de Deus sobre os campos.",
"Forty days after Easter. The Paschal candle is extinguished after the Gospel.": "Quarenta dias depois da Páscoa. Depois do Evangelho apaga-se o círio pascal.",
"The descent of the Holy Spirit upon the apostles.": "A descida do Espírito Santo sobre os apóstolos.",
"Within the octave of Pentecost.": "Na oitava de Pentecostes.",
"The First Sunday after Pentecost.": "Primeiro domingo depois de Pentecostes.",
"The feast of the Most Holy Body of Christ, with its procession of the Blessed Sacrament.": "A festa do Santíssimo Corpo de Cristo, com a sua procissão do Santíssimo Sacramento.",
"The Friday after the octave of Corpus Christi.": "A sexta-feira depois da oitava do Corpus Christi.",
"Its Gospel speaks of the end of the world and the coming of the Son of Man.": "O seu Evangelho fala do fim do mundo e da vinda do Filho do Homem.",
"Kept on the last Sunday of October. Instituted by Pope Pius XI in 1925.": "Celebrada no último domingo de outubro. Instituída pelo papa Pio XI em 1925.",
"Every priest may say three Masses for the dead.": "Cada sacerdote pode dizer três missas pelos defuntos.",
"Every priest may say three Masses for the dead. Kept on November 3 this year, because November 2 is a Sunday.": "Cada sacerdote pode dizer três missas pelos defuntos. Este ano celebra-se a 3 de novembro, porque 2 de novembro é domingo.",
