"AutoMod": "AutoMod",
"Turns back spam before it’s posted, in posts, replies, descriptions, and wiki pages: links to other sites from accounts less than a day old, more than four links, writing in all capitals, long runs of one character, and the same text posted twice within an hour. Moderators aren’t affected. Everything it does is in the log.": "Barra o spam antes de ser publicado, em publicações, respostas, descrições e páginas da wiki: links para outros sites de contas com menos de um dia, mais de quatro links, texto todo em maiúsculas, longas repetições de um caractere e o mesmo texto publicado duas vezes em uma hora. Não afeta os moderadores. Tudo o que ele faz fica no registro.",
"Hide a post or reply until a moderator looks at it once": "Ocultar uma publicação ou resposta até um moderador revê-la quando",
"different members report it.": "membros diferentes a denunciarem.",
"Blocked words": "Palavras bloqueadas",
"Posts and replies that use any of these words (as a whole word) are turned back with a request to rephrase. One word or phrase per line. Moderators aren’t affected.": "Publicações e respostas que usarem alguma dessas palavras (como palavra inteira) são recusadas com um pedido para reformular. Uma palavra ou frase por linha. Não afeta os moderadores.",
"Save blocked words": "Salvar palavras bloqueadas",
"{n} words now": "{n} palavras agora",
