"The wooden statue that wept in a convent chapel in Japan": "A estátua de madeira que chorou na capela de um convento no Japão",
"Akita at Night": "Akita à noite",
"A snowy winter night in northern Japan": "Uma noite de inverno com neve no norte do Japão",
"Zarvanytsia": "Zarvanytsia",
"The wonder-working icon by the spring, beloved of Ukrainian Greek Catholics": "O ícone milagroso junto à fonte, amado pelos greco-católicos ucranianos",
"Zarvanytsia by Candlelight": "Zarvanytsia à luz das velas",
"The pilgrims’ night vigil at the holy spring": "A vigília noturna dos peregrinos junto à fonte santa",
"Sanctify Wine": "Vinho Sanctify",
"The colors of the Sanctify emblem: white on deep wine": "As cores do emblema do Sanctify: branco sobre vinho profundo",
