"Sts. Thomas Aquinas, Albert the Great, Catherine of Siena, Rose of Lima, Martin de Porres, Pius V": "Santo Tomás de Aquino, Santo Alberto Magno, Santa Catarina de Sena, Santa Rosa de Lima, São Martinho de Porres, São Pio V",
"c. 1206–1214 (rule)": "c. 1206–1214 (regra)",
"Sts. Teresa of Ávila, John of the Cross, Thérèse of Lisieux, Edith Stein, Elizabeth of the Trinity": "Santa Teresa de Ávila, São João da Cruz, Santa Teresinha de Lisieux, Santa Edith Stein, Santa Elisabete da Trindade",
"Sts. Rita of Cascia, Nicholas of Tolentino, Thomas of Villanova, Clare of Montefalco": "Santa Rita de Cássia, São Nicolau de Tolentino, São Tomás de Vilanova, Santa Clara de Montefalco",
"The Seven Holy Founders, Sts. Philip Benizi, Peregrine Laziosi, Juliana Falconieri": "Os Sete Santos Fundadores, São Filipe Benício, São Peregrino Laziosi, Santa Juliana Falconieri",
