"Sts. Peter Nolasco, Raymond Nonnatus, Mary de Cervellón": "São Pedro Nolasco, São Raimundo Nonato, Santa Maria de Cervellón",
"Sts. Cajetan, Andrew Avellino, Joseph Mary Tomasi": "São Caetano, Santo André Avelino, São José Maria Tomasi",
"Sts. Anthony Mary Zaccaria, Alexander Sauli, Francis Xavier Bianchi": "Santo Antônio Maria Zaccaria, Santo Alexandre Sauli, São Francisco Xavier Bianchi",
"Sts. Francis Xavier, Peter Canisius, Robert Bellarmine, Aloysius Gonzaga, Isaac Jogues, Peter Claver": "São Francisco Xavier, São Pedro Canísio, São Roberto Belarmino, São Luís Gonzaga, Santo Isaac Jogues, São Pedro Claver",
"Sts. Philip Neri, John Henry Newman, Joseph Vaz": "São Filipe Néri, São John Henry Newman, São José Vaz",
"Sts. Joseph Calasanz, Pompilio Pirrotti": "São José de Calasanz, São Pompílio Pirrotti",
"Sts. Vincent de Paul, Louise de Marillac, Catherine Labouré, Justin de Jacobis": "São Vicente de Paulo, Santa Luísa de Marillac, Santa Catarina Labouré, São Justino de Jacobis",
"Sts. Paul of the Cross, Gabriel of Our Lady of Sorrows, Gemma Galgani (associated), Charles of Mount Argus": "São Paulo da Cruz, São Gabriel de Nossa Senhora das Dores, Santa Gema Galgani (associada), São Carlos de Mount Argus",
"Sts. Alphonsus Liguori, Gerard Majella, John Neumann, Clement Mary Hofbauer; Bls. Zenon Kovalyk, Mykola Charnetskyi": "Santo Afonso de Ligório, São Geraldo Majela, São João Neumann, São Clemente Maria Hofbauer; beatos Zenão Kovalyk, Nicolau Charnetskyi",
"Sts. John Bosco, Dominic Savio, Mary Mazzarello": "São João Bosco, São Domingos Sávio, Santa Maria Mazzarello",
