"Earlier catechisms, now in the public domain, to read right here on Sanctify, a lesson at a time.": "Catecismos antigos, hoje em domínio público, para ler aqui no Sanctify, uma lição de cada vez (em inglês).",
"Catechisms of the Christian East": "Catecismos do Oriente cristão",
"How the Fathers of the East taught the faith to new Christians and to the Church, treasured by Eastern and Latin Catholics alike.": "Como os Padres do Oriente ensinaram a fé aos novos cristãos e à Igreja, apreciados por católicos orientais e latinos.",
"Shorter companions": "Compêndios breves",
"Official summaries of the Catechism of the Catholic Church, in questions and answers.": "Resumos oficiais do Catecismo da Igreja Católica, em perguntas e respostas.",
"Our Father, who art in heaven, hallowed be thy name; thy kingdom come; thy will be done on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses as we forgive those who trespass against us; and lead us not into temptation, but deliver us from the evil one. For yours is the kingdom, and the power, and the glory, of the Father, and of the Son, and of the Holy Spirit, now and ever and unto ages of ages. Amen.": "Pai nosso, que estais nos céus, santificado seja o vosso nome; venha a nós o vosso reino; seja feita a vossa vontade, assim na terra como no céu. O pão nosso de cada dia nos dai hoje; perdoai-nos as nossas ofensas, assim como nós perdoamos a quem nos tem ofendido; e não nos deixeis cair em tentação, mas livrai-nos do maligno. Pois vosso é o reino, o poder e a glória, do Pai, e do Filho, e do Espírito Santo, agora e sempre e pelos séculos dos séculos. Amém.",
"Glory to the Father, and to the Son, and to the Holy Spirit, now and ever and unto ages of ages. Amen.": "Glória ao Pai, e ao Filho, e ao Espírito Santo, agora e sempre e pelos séculos dos séculos. Amém.",
"O Lord and Master of my life, take from me the spirit of sloth, despair, lust of power, and idle talk.": "Senhor e Soberano da minha vida, afasta de mim o espírito de preguiça, de desânimo, de ambição de poder e de palavras vãs.",
"But give rather the spirit of chastity, humility, patience, and love to your servant.": "Concede antes ao teu servo o espírito de castidade, de humildade, de paciência e de amor.",
"Yes, O Lord and King, grant me to see my own transgressions and not to judge my brother, for you are blessed unto ages of ages. Amen.": "Sim, Senhor e Rei, concede-me ver os meus próprios pecados e não julgar o meu irmão, pois és bendito pelos séculos dos séculos. Amém.",
"About 5 minutes": "Cerca de 5 minutos",
"Beginning": "Início",
"In the name of the Father": "Em nome do Pai",
"In the Byzantine tradition the Sign of the Cross is made from right to left, with the thumb and first two fingers joined in honor of the Trinity.": "Na tradição bizantina o sinal da cruz é feito da direita para a esquerda, com o polegar e os dois primeiros dedos unidos em honra da Trindade.",
"To the Holy Spirit": "Ao Espírito Santo",
"O Heavenly King": "Rei celeste",
"The Thrice-Holy Hymn": "O hino três vezes santo",
"Pray it three times, making the Sign of the Cross and bowing each time.": "Reze-o três vezes, fazendo o sinal da cruz e uma inclinação a cada vez.",
"Three times": "Três vezes",
"To the Holy Trinity": "À Santíssima Trindade",
"Glory… O Most Holy Trinity": "Glória… Santíssima Trindade",
"Conclusion": "Conclusão",
"Lord, have mercy": "Senhor, tende piedade",
"Pray it twelve times.": "Reze-o doze vezes.",
"Through the prayers of our holy fathers, Lord Jesus Christ our God, have mercy on us and save us. Amen.": "Pelas orações de nossos santos padres, Senhor Jesus Cristo, nosso Deus, tem piedade de nós e salva-nos. Amém.",
"I believe, O Lord": "Creio, Senhor",
"The Mystical Supper": "A Ceia mística",
"Of your mystical supper": "Da tua Ceia mística",
"For healing": "Para a cura",
"Not unto judgment": "Não para condenação",
"The prayer of the publican": "A oração do publicano",
"O God, be merciful to me": "Ó Deus, tem piedade de mim",
"Pray it three times, bowing each time.": "Reze-o três vezes, inclinando-se a cada vez.",
"Remember me, O Lord, in your kingdom.": "Lembra-te de mim, Senhor, no teu reino.",
"The Angelic Salutation": "A saudação angélica",
"Rejoice, O Virgin Theotokos": "Alegra-te, Virgem Theotokos",
"Axion Estin": "Axion estin",
"The oldest Marian prayer": "A oração mariana mais antiga",
"Beneath Your Compassion": "À vossa proteção",
"Most Holy Theotokos, save us": "Santíssima Theotokos, salva-nos",
"More honorable than the Cherubim, and beyond compare more glorious than the Seraphim.": "Mais venerável que os querubins e incomparavelmente mais gloriosa que os serafins.",
"First part": "Primeira parte",
"O Lord and Master of my life": "Senhor e Soberano da minha vida",
