"Twelve bows": "Doze inclinações",
"O God, cleanse me, a sinner": "Ó Deus, purifica-me, pecador",
"Bow from the waist twelve times, praying these words each time.": "Incline-se doze vezes até a cintura, rezando estas palavras a cada vez.",
"Once more": "Mais uma vez",
"The whole prayer": "A oração inteira",
"Pray the whole prayer again, and make one final prostration.": "Reze de novo a oração inteira e faça uma última prostração.",
